// Returns the aloSIM affiliate URL for a Hebrew destination name.
// With uid: full Everflow per-destination tracking.
// Without uid: correct country page + general affiliate credit.
export function alosimUrlFor(hebrewCountry) {
  if (!hebrewCountry) return `${BASE}/?${AFF}`
  return ALOSIM_COUNTRY_URLS[hebrewCountry] || `${BASE}/?${AFF}`
}
